CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, birth_date DATE, password_hash TEXT NOT NULL, avatar TEXT, onboarding_completed INTEGER DEFAULT 0, phone TEXT, city TEXT, country TEXT, bio TEXT, website TEXT, email_verified INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_preferences (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, hotel_stars TEXT DEFAULT '[]', room_type TEXT DEFAULT '[]', room_view TEXT DEFAULT '[]', hotel_amenities TEXT DEFAULT '[]', flight_type TEXT, seat_class TEXT, seat_position TEXT, preferred_airlines TEXT DEFAULT '[]', max_stops INTEGER, travel_style TEXT DEFAULT '[]', budget_level TEXT, budget_per_night_max INTEGER, noise_sensitivity INTEGER DEFAULT 50, favorite_destinations TEXT DEFAULT '[]', avoid_destinations TEXT DEFAULT '[]', search_history TEXT DEFAULT '[]', booking_history TEXT DEFAULT '[]', ai_profile TEXT DEFAULT '{}', alert_price_drop INTEGER DEFAULT 1, alert_price_rise INTEGER DEFAULT 1, alert_booking_reminder INTEGER DEFAULT 1, alert_weekly_insights INTEGER DEFAULT 1, alert_destination_deals INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hotels (id TEXT PRIMARY KEY, name TEXT NOT NULL, location TEXT NOT NULL, city TEXT NOT NULL, country TEXT NOT NULL, stars INTEGER NOT NULL, description TEXT, amenities TEXT DEFAULT '[]', latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, tripadvisor_url TEXT, tripadvisor_location_id TEXT, tripadvisor_hotel_key TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hotel_rooms (id TEXT PRIMARY KEY, hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE, name TEXT NOT NULL, size_sqm INTEGER, max_guests INTEGER DEFAULT 2, view_type TEXT, amenities TEXT DEFAULT '[]', base_price_per_night DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hotel_prices (id TEXT PRIMARY KEY, hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE, room_id TEXT, operator TEXT NOT NULL, price_per_night DOUBLE PRECISION NOT NULL, total_price DOUBLE PRECISION, check_in DATE, check_out DATE, includes_breakfast INTEGER DEFAULT 0, cancellation_policy TEXT DEFAULT 'flexible', url TEXT, currency TEXT DEFAULT 'USD', tax DOUBLE PRECISION, provider_code TEXT, source TEXT DEFAULT 'local', raw_json TEXT, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hotel_reviews (id TEXT PRIMARY KEY, hotel_id TEXT NOT NULL UNIQUE REFERENCES hotels(id) ON DELETE CASCADE, rating DOUBLE PRECISION NOT NULL, count INTEGER DEFAULT 0, cleanliness DOUBLE PRECISION, service DOUBLE PRECISION, location_score DOUBLE PRECISION, value DOUBLE PRECISION, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS searches (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, destination TEXT NOT NULL, check_in DATE, check_out DATE, guests INTEGER DEFAULT 2, filters TEXT DEFAULT '{}', result_count INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS compare_sessions (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, hotel_ids TEXT NOT NULL, ai_verdict TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookmarks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id, hotel_id));
CREATE TABLE IF NOT EXISTS ai_analyses (id TEXT PRIMARY KEY, hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, check_in DATE, check_out DATE, analysis_json TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_preference_weights (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, score_weights TEXT NOT NULL, declared_weights TEXT NOT NULL, learned_weights TEXT NOT NULL, learning_confidence DOUBLE PRECISION DEFAULT 0, interaction_count INTEGER DEFAULT 0, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_interactions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, hotel_id TEXT REFERENCES hotels(id) ON DELETE SET NULL, event_type TEXT NOT NULL, signal DOUBLE PRECISION DEFAULT 0, context TEXT DEFAULT '{}', session_id TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, user_agent TEXT, ip_address TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), last_seen_at TIMESTAMPTZ DEFAULT NOW(), revoked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS flights (id TEXT PRIMARY KEY, airline TEXT NOT NULL, flight_number TEXT NOT NULL, origin_city TEXT NOT NULL, origin_code TEXT NOT NULL, destination_city TEXT NOT NULL, destination_code TEXT NOT NULL, departure_date DATE NOT NULL, departure_time TEXT NOT NULL, arrival_time TEXT NOT NULL, duration_minutes INTEGER NOT NULL, stops INTEGER DEFAULT 0, cabin_class TEXT DEFAULT 'economy', price DOUBLE PRECISION NOT NULL, seats_left INTEGER DEFAULT 0, aircraft TEXT, baggage TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, pickup_name TEXT NOT NULL, pickup_code TEXT, dropoff_name TEXT NOT NULL, city TEXT NOT NULL, provider TEXT NOT NULL, vehicle_name TEXT NOT NULL, vehicle_type TEXT NOT NULL, max_passengers INTEGER NOT NULL, max_luggage INTEGER NOT NULL, duration_minutes INTEGER NOT NULL, price DOUBLE PRECISION NOT NULL, meet_and_greet INTEGER DEFAULT 0, flight_tracking INTEGER DEFAULT 1, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_interactions_user_created ON user_interactions(user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_prices_hotel_dates ON hotel_prices(hotel_id, check_in, check_out);
CREATE INDEX IF NOT EXISTS idx_hotels_city ON hotels(LOWER(city));
CREATE INDEX IF NOT EXISTS idx_sessions_user ON user_sessions(user_id, revoked_at);
